per {\n  display: flex;\n  justify-content: center;\n  gap: 20px;\n  width: 100%;\n}\n\n.formName,\n.formEmail {\n  width: calc(50% - 10px);\n}\n\n.formText {\n  resize: none;\n\n  width: 100%;\n  height: 150px;\n  margin: 20px 0 0 0;\n}\n\n.formFooter {\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 20px;\n\n  width: 100%;\n  margin: 20px 0 0 0;\n}\n\n.button {\n  cursor: pointer;\n\n  font-family: 'montserrat', sans-serif;\n  font-weight: normal;\n  font-size: 18px;\n  color: var(--color-white);\n\n  height: 45px;\n  padding: 0 25px;\n\n  background-color: rgb(33, 33, 33);\n  border-radius: 8px;\n\n  transition: opacity ease-in-out 0.1s;\n\n  &:hover {\n    opacity: 0.7;\n  }\n}\n\n.formText:user-invalid,\n.formName:user-invalid,\n.formEmail:user-invalid {\n  background-color: rgb(250, 232, 232);\n}\n\n@media screen and (max-width: 925px) {\n  .wrapper {\n    padding: 30px 20px 100px 20px;\n  }\n\n  .formName,\n  .formEmail {\n    width: calc(50% - 8px);\n  }\n\n  .formText,\n  .formName,\n  .formEmail {\n    font-size: 16px;\n  }\n\n  .button {\n    font-size: 16px;\n  }\n\n  .formFooter {\n    flex-wrap: wrap;\n    justify-content: center;\n  }\n}\n"],"names":[],"mappings":"AAAA;;;;;;;;;;;;;;AAkBA;;;;;;;AAWA;;;;;;;AAQA;;;;;;;;AAQA;;;;AAIA;;;;AAIA;;;;AAIA;;;;;;AAOA;;;;;;;AAQA;;;;;;;;;;AAWA;;;;;;;;;AAYE;;;;AAKF;;;;;;;AAOA;;;;;;;AAOA;;;;AAKA;;;;;;;AAQA;;;;;;;;;AAUA;;;;;;;;;;;;;AAgBE;;;;AAKF;;;;AAMA;EACE;;;;EAIA;;;;EAKA;;;;EAUA"}}]
